  if (v.npcs[id] && v.npcs[id].name === 'Frank') { frankId = id; break; }
}
// Find loc_franks_office id
let officeId = null;
for (const lid of Object.keys(setup.locations || {})) {
  if ((setup.locations[lid].slug || setup.locations[lid].name || '').toLowerCase().includes('office')) {
    officeId = lid;
    break;
  }
}
// Get available canvases for this location
