  setup.selectNpcPortraitCanvasesForLocation(officeId) : null;
return JSON.stringify({
  frank_id: frankId,
  office_id: officeId,
  frank_loc: setup.getNpcLocation(frankId),
  portrait_canvases: portraitCanvases,
}, null, 2);

