const setup = SugarCube.setup;
const helpData = setup.help_data || {};
const officeCanvases = (helpData.locationCanvases || {}).loc_franks_office || [];
// Find setter
const setterCanvas = officeCanvases.find(c => /office.*activity menu|setter/i.test(c.name || ''));
const validation = setterCanvas ? {
  id: setterCanvas.id,
  name: setterCanvas.name,
  isRepeatable: setterCanvas.isRepeatable,
  triggerMode: setterCanvas.triggerMode,
  npcId: setterCanvas.npcId,
  isValid: setup.isCanvasValid(setterCanvas),
  canTrigger: setup.canTriggerActivity(setterCanvas.name || setterCanvas.id, setterCanvas.maxPerDay),
  conditions: setterCanvas.conditions,
  schedules: setterCanvas.schedules,
} : null;
return JSON.stringify({
  canvas_count: officeCanvases.length,
  canvas_names: officeCanvases.map(c => c.name),
  setter: validation,
}, null, 2);

