const setup = SugarCube.setup;
const SC = window.SugarCube;
// Find office location id
const locs = setup.locations || {};
let officeId = null;
for (const lid of Object.keys(locs)) {
  if ((locs[lid].name || '').toLowerCase().includes('office')) { officeId = lid; break; }
}
const helpData = setup.help_data || {};
const officeCanvases = (helpData.locationCanvases || {})[officeId] || [];
return JSON.stringify({
  office_id: officeId,
  office_name: locs[officeId] ? locs[officeId].name : null,
  canvas_count: officeCanvases.length,
  canvases: officeCanvases.map(c => ({ name: c.name, id: c.id, isRepeatable: c.isRepeatable, npcId: c.npcId, isValid: setup.isCanvasValid(c) })),
}, null, 2);

const helpData = SugarCube.setup.help_data || {};
const lc = helpData.locationCanvases || {};
// Find any location with Frank canvases
const out = {};
for (const lid of Object.keys(lc)) {
  const list = lc[lid];
  if (!list || !list.length) continue;
  const frankCanvases = list.filter(c => /office.*activity|office_setter/i.test(c.name || c.id || ''));
  if (frankCanvases.length) {
    out[lid] = frankCanvases.map(c => ({name: c.name, id: c.id, isRepeatable: c.isRepeatable, npcId: c.npcId}));
  }
}
return JSON.stringify(out, null, 2);

